const b = $('Webhook').item.json.body;
const pr = b.pull_request;
const args = {
  surface: 'pr-review-requested',
  repoOwner: b.repository.owner.login,
  repoName: b.repository.name,
  repoFull: b.repository.full_name,
  senderLogin: b.sender && b.sender.login,
  senderType: b.sender && b.sender.type,
  prNumber: pr.number,
  prTitle: pr.title,
  prBody: pr.body || '',
  prHeadRef: pr.head && pr.head.ref,
  prBaseRef: pr.base && pr.base.ref,
  prHeadSha: pr.head && pr.head.sha,
  reviewerLogin: (b.requested_reviewer && b.requested_reviewer.login) || '',
  title: pr.title,
  bodyText: pr.body || '',
};
const prompt = `Review PR #${args.prNumber}: ${args.prTitle}

PR body:
---
${args.prBody}
---

Output a one-line verdict (APPROVE / REQUEST_CHANGES / COMMENT) followed by bullet findings with \`file:line\` refs. Keep it under 30 lines. The diff is appended after a "=== DIFF ===" line by the agent script before claude runs.
`;
args.promptB64 = Buffer.from(prompt, 'utf8').toString('base64');
return [{ json: { argsB64: Buffer.from(JSON.stringify(args), 'utf8').toString('base64') } }];
